    /// Function `R4.Learning.parameterError`.
    pub fn parameter_error(state: ModelState, parameter: Parameter) -> Option<LearningError> {
        match parameter.clone() {
            Parameter::Route(index) => {
                if (!(super::r4_configuration::is_word(index.clone()))) {
                    Some(LearningError::OutsideWord)
                } else {
                    if gated(((state.clone()).binding.clone()).read.clone()) {
                        Some(LearningError::InactiveRoute)
                    } else {
                        if ((index.clone()) < (length_routes((state.clone()).routes.clone()))) {
                            None::<LearningError>
                        } else {
                            Some(LearningError::BadIndex)
                        }
                    }
                }
            }
            Parameter::VectorBlock(index) => {
                if (!(super::r4_configuration::is_word(index.clone()))) {
                    Some(LearningError::OutsideWord)
                } else {
                    if ((index.clone())
                        < (super::r4_configuration::product(
                            (((state.clone()).binding.clone()).spec.clone())
                                .vocabulary
                                .clone(),
                            (((state.clone()).binding.clone()).spec.clone())
                                .blocks
                                .clone(),
                        )))
                    {
                        None::<LearningError>
                    } else {
                        Some(LearningError::BadIndex)
                    }
                }
            }
            Parameter::Gate(index) => {
                if (!(super::r4_configuration::is_word(index.clone()))) {
                    Some(LearningError::OutsideWord)
                } else {
                    if (!(gated(((state.clone()).binding.clone()).read.clone()))) {
                        Some(LearningError::InactiveGate)
                    } else {
                        if ((index.clone()) < (length_gates((state.clone()).gates.clone()))) {
                            None::<LearningError>
                        } else {
                            Some(LearningError::BadIndex)
                        }
                    }
                }
            }
        }
    }

