    /// Function `R4.Learning.performMove`.
    pub fn perform_move(state: ModelState, parameter: Parameter, ordinal: u64) -> ApplyOutcome {
        match parameter.clone() {
            Parameter::Route(index) => {
                match geometric_port(state.clone(), parameter.clone(), ordinal.clone()) {
                    None => ApplyOutcome {
                        state: state.clone(),
                        status: ApplyStatus::Rejected(LearningError::InvalidGeometry),
                    },
                    Some(port) => commit_routes(
                        state.clone(),
                        replace_route((state.clone()).routes.clone(), index.clone(), port.clone()),
                    ),
                }
            }
            Parameter::VectorBlock(index) => match candidate_action(ordinal.clone()) {
                None => ApplyOutcome {
                    state: state.clone(),
                    status: ApplyStatus::Rejected(LearningError::InvalidGeometry),
                },
                Some(r#move) => {
                    match lookup_root((state.clone()).codebook.clone(), index.clone()) {
                        None => ApplyOutcome {
                            state: state.clone(),
                            status: ApplyStatus::Rejected(LearningError::InvalidGeometry),
                        },
                        Some(current) => commit_roots(
                            state.clone(),
                            replace_root(
                                (state.clone()).codebook.clone(),
                                index.clone(),
                                super::r4_geometry::apply(r#move.clone(), current.clone()),
                            ),
                        ),
                    }
                }
            },
            Parameter::Gate(index) => {
                match lookup_gate((state.clone()).gates.clone(), index.clone()) {
                    None => ApplyOutcome {
                        state: state.clone(),
                        status: ApplyStatus::Rejected(LearningError::InvalidGeometry),
                    },
                    Some(current) => {
                        match super::r4_gates::gate_candidate(current.clone(), ordinal.clone()) {
                            None => ApplyOutcome {
                                state: state.clone(),
                                status: ApplyStatus::Rejected(LearningError::InvalidGeometry),
                            },
                            Some(value) => commit_gates(
                                state.clone(),
                                replace_gate(
                                    (state.clone()).gates.clone(),
                                    index.clone(),
                                    value.clone(),
                                ),
                            ),
                        }
                    }
                }
            }
        }
    }

