    /// Function `R4.Learning.eligibleWriterRow`.
    pub fn eligible_writer_row(
        baseline: super::r4_admission::WriterOutcome,
        candidate: super::r4_admission::WriterOutcome,
    ) -> RowOutcome {
        if writer_observation_admitted(candidate.clone()) {
            match super::r4_admission::eligibility(
                baseline.clone(),
                normalize_writer(candidate.clone()),
            ) {
                super::r4_admission::Eligibility::SkippedBaseline => RowOutcome::Skipped,
                super::r4_admission::Eligibility::LostRival => RowOutcome::Unavailable,
                super::r4_admission::Eligibility::Unavailable => RowOutcome::Unavailable,
                super::r4_admission::Eligibility::Eligible(cost) => RowOutcome::Cost(cost.clone()),
                super::r4_admission::Eligibility::Error(reason) => {
                    RowOutcome::Error(BatchError::CandidateWriter(reason.clone()))
                }
            }
        } else {
            RowOutcome::Error(BatchError::OutsideWord)
        }
    }

    /// Function `R4.Learning.baselineWriterRow`.
    pub fn baseline_writer_row(
        baseline: super::r4_admission::WriterOutcome,
        candidate: ReadOutcome,
    ) -> RowOutcome {
        if (!(writer_observation_admitted(baseline.clone()))) {
            RowOutcome::Error(BatchError::OutsideWord)
        } else {
            match normalize_writer(baseline.clone()) {
                super::r4_admission::WriterOutcome::Error(reason) => {
                    RowOutcome::Error(BatchError::BaselineWriter(reason.clone()))
                }
                super::r4_admission::WriterOutcome::Value(receipt) => {
                    if (((receipt.clone()).token_rivals.clone()) == (0u64)) {
                        RowOutcome::Skipped
                    } else {
                        match candidate.clone() {
                            ReadOutcome::ReadFailure => {
                                RowOutcome::Error(BatchError::CandidateRead)
                            }
                            ReadOutcome::Scored(writer) => {
                                eligible_writer_row(baseline.clone(), writer.clone())
                            }
                        }
                    }
                }
            }
        }
    }

    /// Function `R4.Learning.rowOutcome`.
    pub fn row_outcome(baseline: ReadOutcome, candidate: ReadOutcome) -> RowOutcome {
        match baseline.clone() {
            ReadOutcome::ReadFailure => RowOutcome::Error(BatchError::BaselineRead),
            ReadOutcome::Scored(writer) => baseline_writer_row(writer.clone(), candidate.clone()),
        }
    }

