    /// Function `R4.Engine.initialGates`.
    pub fn initial_gates(
        binding: super::r4_learning::Binding,
        stages: u64,
    ) -> Result<Vec<super::r4_gates::Trit>, EngineError> {
        match super::r4_configuration::gate_count(
            (binding.clone()).read.clone(),
            ((binding.clone()).spec.clone()).blocks.clone(),
            stages.clone(),
        ) {
            super::r4_configuration::GateOutcome::Count(count) => {
                Ok::<Vec<super::r4_gates::Trit>, EngineError>(
                    if super::r4_configuration::is_zero_gates(
                        (binding.clone()).initialization.clone(),
                    ) {
                        repeat_gate(count.clone(), super::r4_gates::Trit::Zero)
                    } else {
                        append_gate_padding(
                            count.clone(),
                            super::r4_configuration::product(
                                ((binding.clone()).spec.clone()).blocks.clone(),
                                stages.clone(),
                            ),
                            stages.clone(),
                        )
                    },
                )
            }
            super::r4_configuration::GateOutcome::Overflow => {
                Err::<Vec<super::r4_gates::Trit>, EngineError>(EngineError::CountOverflow)
            }
            super::r4_configuration::GateOutcome::OutsideWord => {
                Err::<Vec<super::r4_gates::Trit>, EngineError>(EngineError::OutsideWord)
            }
        }
    }

    /// Function `R4.Engine.initializeModel`.
    pub fn initialize_model(
        binding: super::r4_learning::Binding,
    ) -> Result<super::r4_learning::ModelState, EngineError> {
        if super::r4_learning::binding_admitted(binding.clone()) {
            match super::r4_binder::construct(((binding.clone()).spec.clone()).context.clone()) {
                super::r4_binder::Construction::InvalidContext => {
                    Err::<super::r4_learning::ModelState, EngineError>(EngineError::InvalidModel)
                }
                super::r4_binder::Construction::Built(global) => {
                    match seed_roots(
                        super::r4_configuration::product(
                            ((binding.clone()).spec.clone()).vocabulary.clone(),
                            ((binding.clone()).spec.clone()).blocks.clone(),
                        ),
                        0u64,
                        (binding.clone()).seed.clone(),
                    ) {
                        Err(failure) => {
                            Err::<super::r4_learning::ModelState, EngineError>(failure.clone())
                        }
                        Ok(roots) => {
                            match initial_gates(binding.clone(), (global.clone()).stages.clone()) {
                                Err(failure) => Err::<super::r4_learning::ModelState, EngineError>(
                                    failure.clone(),
                                ),
                                Ok(gates) => admit_model(super::r4_learning::ModelState {
                                    binding: binding.clone(),
                                    epoch: 0u64,
                                    codebook: roots.clone(),
                                    routes: repeat_nat(
                                        super::r4_configuration::product(
                                            ((binding.clone()).spec.clone()).blocks.clone(),
                                            (global.clone()).stages.clone(),
                                        ),
                                        0u64,
                                    ),
                                    gates: gates.clone(),
                                }),
                            }
                        }
                    }
                }
            }
        } else {
            Err::<super::r4_learning::ModelState, EngineError>(EngineError::InvalidModel)
        }
    }

