    /// Function `R4.Engine.planWordsUnchecked`.
    pub fn plan_words_unchecked(
        global: super::r4_binder::BinderPlan,
        row: super::r4_binder::BinderPlan,
    ) -> Vec<u64> {
        append_nat(
            {
                let mut __v = vec![(row.clone()).context.clone()];
                __v.extend({
                    let mut __v = vec![super::r4_binder::length_node((row.clone()).nodes.clone())];
                    __v.extend({
                        let mut __v = vec![length_nat((row.clone()).frontier.clone())];
                        __v.extend(Vec::<u64>::new());
                        __v
                    });
                    __v
                });
                __v
            },
            append_nat(
                super::r4_binder::node_words((row.clone()).nodes.clone()),
                append_nat(
                    repeat_nat(
                        super::r4_configuration::product(
                            super::r4_objective::subtract_nat(
                                super::r4_binder::length_node((global.clone()).nodes.clone()),
                                super::r4_binder::length_node((row.clone()).nodes.clone()),
                            ),
                            4u64,
                        ),
                        4294967295u64,
                    ),
                    append_nat(
                        (row.clone()).frontier.clone(),
                        repeat_nat(
                            super::r4_objective::subtract_nat(
                                16u64,
                                length_nat((row.clone()).frontier.clone()),
                            ),
                            4294967295u64,
                        ),
                    ),
                ),
            ),
        )
    }

    /// Function `R4.Engine.planWords`.
    pub fn plan_words(
        global: super::r4_binder::BinderPlan,
        row: super::r4_binder::BinderPlan,
    ) -> Result<Vec<u64>, EngineError> {
        match super::r4_binder::validate(global.clone()) {
            super::r4_binder::Validation::Invalid(reason) => {
                Err::<Vec<u64>, EngineError>(EngineError::RowShape)
            }
            super::r4_binder::Validation::Valid => match super::r4_binder::validate(row.clone()) {
                super::r4_binder::Validation::Invalid(reason) => {
                    Err::<Vec<u64>, EngineError>(EngineError::RowShape)
                }
                super::r4_binder::Validation::Valid => {
                    if ((((row.clone()).context.clone()) <= ((global.clone()).context.clone()))
                        && (((super::r4_binder::length_node((row.clone()).nodes.clone()))
                            <= (super::r4_binder::length_node((global.clone()).nodes.clone())))
                            && ((length_nat((row.clone()).frontier.clone())) <= (16u64))))
                    {
                        Ok::<Vec<u64>, EngineError>(plan_words_unchecked(
                            global.clone(),
                            row.clone(),
                        ))
                    } else {
                        Err::<Vec<u64>, EngineError>(EngineError::RowShape)
                    }
                }
            },
        }
    }

