    /// Function `R4.Engine.buildWindows`.
    pub fn build_windows(
        windows: Vec<Vec<Identity>>,
        context: u64,
    ) -> Result<RowsPhysical, EngineError> {
        {
            let __scrut = windows.clone();
            if __scrut.is_empty() {
                Ok::<RowsPhysical, EngineError>(RowsPhysical {
                    rows: Vec::<Row>::new(),
                    identities: Vec::<Identity>::new(),
                })
            } else {
                let head = __scrut[0].clone();
                let tail = __scrut[1..].to_vec();
                {
                    let __scrut = head.clone();
                    if __scrut.is_empty() {
                        Err::<RowsPhysical, EngineError>(EngineError::Windows)
                    } else {
                        let first = __scrut[0].clone();
                        let rest = __scrut[1..].to_vec();
                        if (((length_identity(rest.clone())).saturating_add(1u64))
                            <= (context.clone()))
                        {
                            match super::r4_binder::construct(
                                (length_identity(rest.clone())).saturating_add(1u64),
                            ) {
                                super::r4_binder::Construction::InvalidContext => {
                                    Err::<RowsPhysical, EngineError>(EngineError::Windows)
                                }
                                super::r4_binder::Construction::Built(canonical) => {
                                    match build_windows(tail.clone(), context.clone()) {
                                        Err(failure) => {
                                            Err::<RowsPhysical, EngineError>(failure.clone())
                                        }
                                        Ok(built) => {
                                            Ok::<RowsPhysical, EngineError>(RowsPhysical {
                                                rows: {
                                                    let mut __v = vec![Row {
                                                        identities: {
                                                            let mut __v = vec![first.clone()];
                                                            __v.extend(rest.clone());
                                                            __v
                                                        },
                                                        plan: canonical.clone(),
                                                    }];
                                                    __v.extend((built.clone()).rows.clone());
                                                    __v
                                                },
                                                identities: append_identity(
                                                    {
                                                        let mut __v = vec![first.clone()];
                                                        __v.extend(rest.clone());
                                                        __v
                                                    },
                                                    append_identity(
                                                        repeat_identity(
                                                            super::r4_objective::subtract_nat(
                                                                context.clone(),
                                                                (length_identity(rest.clone()))
                                                                    .saturating_add(1u64),
                                                            ),
                                                            first.clone(),
                                                        ),
                                                        (built.clone()).identities.clone(),
                                                    ),
                                                ),
                                            })
                                        }
                                    }
                                }
                            }
                        } else {
                            Err::<RowsPhysical, EngineError>(EngineError::Windows)
                        }
                    }
                }
            }
        }
    }

    /// Function `R4.Engine.lengthWindows`.
