    /// Function `R4.Engine.splitIndexSteps`.
    pub fn split_index_steps(remaining: u64, unit: u64, major: u64, minor: u64) -> IndexParts {
        {
            let __scrut = remaining.clone();
            if __scrut == 0 {
                IndexParts {
                    major: major.clone(),
                    minor: minor.clone(),
                }
            } else {
                let prior = __scrut - 1;
                if (((minor.clone()).saturating_add(1u64)) == (unit.clone())) {
                    split_index_steps(
                        prior.clone(),
                        unit.clone(),
                        (major.clone()).saturating_add(1u64),
                        0u64,
                    )
                } else {
                    split_index_steps(
                        prior.clone(),
                        unit.clone(),
                        major.clone(),
                        (minor.clone()).saturating_add(1u64),
                    )
                }
            }
        }
    }

    /// Function `R4.Engine.splitIndex`.
