    /// Function `R4.Engine.writerView`.
    pub fn writer_view(
        model: super::r4_learning::ModelState,
        parameter: super::r4_learning::Parameter,
        candidate: u64,
    ) -> super::r4_admission::View {
        if ((candidate.clone()) == (0u64)) {
            super::r4_admission::View::Current
        } else {
            match parameter.clone() {
                super::r4_learning::Parameter::VectorBlock(index) => {
                    super::r4_admission::View::VectorMove(
                        (split_index(
                            index.clone(),
                            (((model.clone()).binding.clone()).spec.clone())
                                .blocks
                                .clone(),
                        ))
                        .major
                        .clone(),
                        (split_index(
                            index.clone(),
                            (((model.clone()).binding.clone()).spec.clone())
                                .blocks
                                .clone(),
                        ))
                        .minor
                        .clone(),
                        candidate.clone(),
                    )
                }
                super::r4_learning::Parameter::Route(index) => super::r4_admission::View::Current,
                super::r4_learning::Parameter::Gate(index) => super::r4_admission::View::Current,
            }
        }
    }

    /// Function `R4.Engine.routeView`.
