    /// Function `R4.Engine.forward`.
    pub fn forward(
        model: super::r4_learning::ModelState,
        batch: CarriedBatch,
        targets: Vec<u64>,
        trace: bool,
    ) -> Result<Forward, EngineError> {
        if ((trace.clone())
            && (!(super::r4_learning::gated(((model.clone()).binding.clone()).read.clone()))))
        {
            Err::<Forward, EngineError>(EngineError::UnsupportedTrace)
        } else {
            match admit_batch(model.clone(), batch.clone(), targets.clone()) {
                None => {
                    match forward_rows(
                        (batch.clone()).rows.clone(),
                        (batch.clone()).entries.clone(),
                        targets.clone(),
                        model.clone(),
                        0u64,
                        trace.clone(),
                    ) {
                        Err(failure) => Err::<Forward, EngineError>(failure.clone()),
                        Ok(rows) => Ok::<Forward, EngineError>(Forward {
                            binding: (model.clone()).binding.clone(),
                            epoch: (model.clone()).epoch.clone(),
                            traced: trace.clone(),
                            rows: rows.clone(),
                        }),
                    }
                }
                Some(failure) => Err::<Forward, EngineError>(failure.clone()),
            }
        }
    }

