    /// Function `R4.Engine.traceWords`.
    pub fn trace_words(
        model: super::r4_learning::ModelState,
        trace_words_input_forward: Forward,
    ) -> Result<Vec<u64>, EngineError> {
        if (trace_words_input_forward.clone()).traced.clone() {
            match ((model.clone()).binding.clone()).read.clone() {
                super::r4_configuration::ReadSpec::Route => {
                    Err::<Vec<u64>, EngineError>(EngineError::UnsupportedTrace)
                }
                super::r4_configuration::ReadSpec::Flock(kept) => Ok::<Vec<u64>, EngineError>(
                    forward_trace_words((trace_words_input_forward.clone()).rows.clone()),
                ),
                super::r4_configuration::ReadSpec::Relation(kept, sweeps) => {
                    match super::r4_binder::construct(
                        (((model.clone()).binding.clone()).spec.clone())
                            .context
                            .clone(),
                    ) {
                        super::r4_binder::Construction::InvalidContext => {
                            Err::<Vec<u64>, EngineError>(EngineError::InvalidModel)
                        }
                        super::r4_binder::Construction::Built(global) => {
                            match forward_score_words(
                                (trace_words_input_forward.clone()).rows.clone(),
                                super::r4_binder::length_node((global.clone()).nodes.clone()),
                            ) {
                                Err(failure) => Err::<Vec<u64>, EngineError>(failure.clone()),
                                Ok(scores) => Ok::<Vec<u64>, EngineError>(append_nat(
                                    forward_trace_words(
                                        (trace_words_input_forward.clone()).rows.clone(),
                                    ),
                                    scores.clone(),
                                )),
                            }
                        }
                    }
                }
            }
        } else {
            Err::<Vec<u64>, EngineError>(EngineError::UnsupportedTrace)
        }
    }

    /// Function `R4.Engine.candidateRow`.
    pub fn candidate_row(
        model: super::r4_learning::ModelState,
        row: Row,
        entries: Vec<super::r4_route::Entry>,
        target: u64,
        parameter: super::r4_learning::Parameter,
        candidate: u64,
        row_index: u64,
    ) -> Result<super::r4_learning::RowOutcome, EngineError> {
        match read_row(
            model.clone(),
            row.clone(),
            entries.clone(),
            parameter.clone(),
            0u64,
            row_index.clone(),
            true,
            false,
        ) {
            Err(failure) => Err::<super::r4_learning::RowOutcome, EngineError>(failure.clone()),
            Ok(baseline_read) => {
                match super::r4_learning::normalize_writer(writer_for(
                    model.clone(),
                    (baseline_read.clone()).outputs.clone(),
                    target.clone(),
                    parameter.clone(),
                    0u64,
                )) {
                    super::r4_admission::WriterOutcome::Error(reason) => {
                        Err::<super::r4_learning::RowOutcome, EngineError>(EngineError::Writer(
                            row_index.clone(),
                            candidate.clone(),
                            true,
                            reason.clone(),
                        ))
                    }
                    super::r4_admission::WriterOutcome::Value(baseline_writer) => {
                        if (((baseline_writer.clone()).token_rivals.clone()) == (0u64)) {
                            Ok::<super::r4_learning::RowOutcome, EngineError>(
                                super::r4_learning::RowOutcome::Skipped,
                            )
                        } else {
                            match read_row(
                                model.clone(),
                                row.clone(),
                                entries.clone(),
                                parameter.clone(),
                                candidate.clone(),
                                row_index.clone(),
                                false,
                                false,
                            ) {
                                Err(failure) => Err::<super::r4_learning::RowOutcome, EngineError>(
                                    failure.clone(),
                                ),
                                Ok(candidate_read) => {
                                    Ok::<super::r4_learning::RowOutcome, EngineError>(
                                        super::r4_learning::eligible_writer_row(
                                            super::r4_admission::WriterOutcome::Value(
                                                baseline_writer.clone(),
                                            ),
                                            writer_for(
                                                model.clone(),
                                                (candidate_read.clone()).outputs.clone(),
                                                target.clone(),
                                                parameter.clone(),
                                                candidate.clone(),
                                            ),
                                        ),
                                    )
                                }
                            }
                        }
                    }
                }
            }
        }
    }

    /// Function `R4.Engine.candidateRows`.
    pub fn candidate_rows(
        rows: Vec<Row>,
        entries: Vec<super::r4_route::Entry>,
        targets: Vec<u64>,
        model: super::r4_learning::ModelState,
        parameter: super::r4_learning::Parameter,
        candidate: u64,
        row_index: u64,
        sum: u64,
        eligible: u64,
    ) -> Result<u64, EngineError> {
        {
            let __scrut = rows.clone();
            if __scrut.is_empty() {
                if ((eligible.clone()) == (0u64)) {
                    Err::<u64, EngineError>(EngineError::Aggregate(
                        candidate.clone(),
                        super::r4_learning::BatchError::NoEligible,
                    ))
                } else {
                    Ok::<u64, EngineError>(sum.clone())
                }
            } else {
                let head = __scrut[0].clone();
                let tail = __scrut[1..].to_vec();
                {
                    let __scrut = targets.clone();
                    if __scrut.is_empty() {
                        Err::<u64, EngineError>(EngineError::Targets)
                    } else {
                        let target = __scrut[0].clone();
                        let rest_targets = __scrut[1..].to_vec();
                        match candidate_row(
                            model.clone(),
                            head.clone(),
                            entries.clone(),
                            target.clone(),
                            parameter.clone(),
                            candidate.clone(),
                            row_index.clone(),
                        ) {
                            Err(failure) => Err::<u64, EngineError>(failure.clone()),
                            Ok(outcome) => match outcome.clone() {
                                super::r4_learning::RowOutcome::Skipped => candidate_rows(
                                    tail.clone(),
                                    drop_entry(
                                        (((model.clone()).binding.clone()).spec.clone())
                                            .context
                                            .clone(),
                                        entries.clone(),
                                    ),
                                    rest_targets.clone(),
                                    model.clone(),
                                    parameter.clone(),
                                    candidate.clone(),
                                    (row_index.clone()).saturating_add(1u64),
                                    sum.clone(),
                                    eligible.clone(),
                                ),
                                super::r4_learning::RowOutcome::Unavailable => {
                                    Ok::<u64, EngineError>(18446744073709551615u64)
                                }
                                super::r4_learning::RowOutcome::Error(reason) => {
                                    Err::<u64, EngineError>(EngineError::Aggregate(
                                        candidate.clone(),
                                        reason.clone(),
                                    ))
                                }
                                super::r4_learning::RowOutcome::Cost(cost) => {
                                    if super::r4_learning::word64(
                                        (sum.clone()).saturating_add(cost.clone()),
                                    ) {
                                        candidate_rows(
                                            tail.clone(),
                                            drop_entry(
                                                (((model.clone()).binding.clone()).spec.clone())
                                                    .context
                                                    .clone(),
                                                entries.clone(),
                                            ),
                                            rest_targets.clone(),
                                            model.clone(),
                                            parameter.clone(),
                                            candidate.clone(),
                                            (row_index.clone()).saturating_add(1u64),
                                            (sum.clone()).saturating_add(cost.clone()),
                                            (eligible.clone()).saturating_add(1u64),
                                        )
                                    } else {
                                        Err::<u64, EngineError>(EngineError::Aggregate(
                                            candidate.clone(),
                                            super::r4_learning::BatchError::ArithmeticOverflow,
                                        ))
                                    }
                                }
                            },
                        }
                    }
                }
            }
        }
    }

